//! Compares `js_number_string` with Go's `JSNumberString` through fixtures
//! generated by `tests/data/jsnumber/gen.go`, so the test never needs Go.

use std::fs;
use std::path::PathBuf;

use regex as _;
use rotor_luau::js_number_string;

fn fixture(name: &str) -> PathBuf {
	[env!("CARGO_MANIFEST_DIR"), "tests", "data", "jsnumber", name]
		.iter()
		.collect()
}

/// splitmix64, matching the generator.
const fn splitmix(state: &mut u64) -> u64 {
	*state = state.wrapping_add(0x9E37_79B9_7F4A_7C15);
	let mut z = *state;
	z = (z ^ (z >> 30)).wrapping_mul(0xBF58_476D_1CE4_E5B9);
	z = (z ^ (z >> 27)).wrapping_mul(0x94D0_49BB_1331_11EB);
	z ^ (z >> 31)
}

#[test]
fn js_number_string_matches_go_edges() {
	let text = fs::read_to_string(fixture("edges.txt")).expect("read edges.txt");
	let mut count = 0;
	for line in text.lines() {
		let (bits, want) = line.split_once(' ').expect("`<bits> <expected>` line");
		let value = f64::from_bits(u64::from_str_radix(bits, 16).expect("hex bits"));
		assert_eq!(js_number_string(value), want, "bits {bits} ({value:e})");
		count += 1;
	}
	assert!(count >= 40, "edges fixture has {count} lines");
}

#[test]
fn js_number_string_matches_go_random_bits() {
	let text = fs::read_to_string(fixture("random.txt")).expect("read random.txt");
	let mut state = 1337;
	let mut mismatches = Vec::new();
	let mut count = 0;
	for want in text.lines() {
		let bits = splitmix(&mut state);
		let got = js_number_string(f64::from_bits(bits));
		if got != want {
			mismatches.push(format!("{bits:016x}: got {got}, want {want}"));
		}
		count += 1;
	}
	assert_eq!(count, 200_000, "random fixture length");
	assert!(
		mismatches.is_empty(),
		"{} mismatches, first: {:?}",
		mismatches.len(),
		&mismatches[..mismatches.len().min(5)]
	);
}
